use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

fn w1(c: Arc<AtomicUsize>) {
    let mut expected = c.load(Ordering::SeqCst);
    loop {
        match c.compare_exchange(expected, expected + 1, Ordering::SeqCst, Ordering::SeqCst) {
            Ok(_) => break,
            Err(actual) => expected = actual,
        }
    }
}

fn w2(c: Arc<AtomicUsize>) {
    let mut expected = c.load(Ordering::SeqCst);
    loop {
        match c.compare_exchange(expected, expected + 1, Ordering::SeqCst, Ordering::SeqCst) {
            Ok(_) => break,
            Err(actual) => expected = actual,
        }
    }
}

fn main() {
    let c = Arc::new(AtomicUsize::new(0));
    let c1 = Arc::clone(&c);
    let c2 = Arc::clone(&c);

    let h1 = thread::spawn(move || w1(c1));
    let h2 = thread::spawn(move || w2(c2));

    h1.join().unwrap();
    h2.join().unwrap();

    println!("DONE done=1");
}
