use std::sync::mpsc::{sync_channel, Receiver, SyncSender};
use std::sync::{Arc, Mutex};

fn sender(m: Arc<Mutex<()>>, ch: SyncSender<i32>) {
    {
        let _g = m.lock().unwrap();
    }
    ch.send(1).unwrap();
    {
        let _g = m.lock().unwrap();
    }
    ch.send(2).unwrap();
}

fn receiver(m: Arc<Mutex<()>>, ch: Receiver<i32>) {
    let v1 = ch.recv().unwrap();
    {
        let _g = m.lock().unwrap();
    }
    let v2 = ch.recv().unwrap();
    {
        let _g = m.lock().unwrap();
    }
    let _ = (v1, v2);
}

fn main() {
    let m = Arc::new(Mutex::new(()));
    let (ch_tx, ch_rx) = sync_channel::<i32>(1);

    let m_sender = Arc::clone(&m);
    let h_sender = std::thread::spawn(move || sender(m_sender, ch_tx));

    let m_receiver = Arc::clone(&m);
    let h_receiver = std::thread::spawn(move || receiver(m_receiver, ch_rx));

    h_sender.join().unwrap();
    h_receiver.join().unwrap();

    println!("DONE done=1");
}
```

